import { GoogleGenAI, Type } from "@google/genai";
import { MOCK_SCHEMES } from "../constants";

/**
 * Searches for relevant schemes using Gemini AI with Google Search Grounding.
 * This ensures the AI can find real-time updates for 2025-2026 schemes.
 */
export const searchSchemesAI = async (query: string) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `User Query: "${query}". Search our database first, then use Google Search to find if there are any brand new 2025-2026 schemes not yet in my list.`,
      config: {
        systemInstruction: `You are the "Gov-Smart 2025-26 Navigator". 
        Your task is to identify relevant government schemes from the provided database and use Google Search to find real-time 2025 updates.

        DATABASE: ${JSON.stringify(MOCK_SCHEMES.map(s => ({ 
          id: s.id, 
          title: s.title, 
          description: s.description, 
          category: s.category 
        })))}

        RULES:
        1. Return a JSON array containing the string IDs of relevant database schemes.
        2. If you find a relevant 2025 scheme via Google Search that is NOT in the database, return its details as a virtual object in the array with a 'virtual: true' property.
        3. Prioritize precision for the Indian fiscal year 2025-2026.
        4. Output MUST be valid JSON.`,
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              id: { type: Type.STRING },
              title: { type: Type.STRING },
              description: { type: Type.STRING },
              category: { type: Type.STRING },
              virtual: { type: Type.BOOLEAN }
            }
          }
        }
      }
    });

    const text = response.text || '[]';
    const results = JSON.parse(text);

    // Merge database schemes with any virtual search results
    const finalResults: any[] = [];
    results.forEach((res: any) => {
      const dbScheme = MOCK_SCHEMES.find(s => s.id === res.id);
      if (dbScheme) {
        finalResults.push(dbScheme);
      } else if (res.virtual) {
        // Construct a virtual scheme object for UI display
        finalResults.push({
          ...res,
          level: 'Central',
          updatedAt: 'LIVE 2025',
          ministry: 'External Source',
          isLiveResult: true
        });
      }
    });

    return finalResults.length > 0 ? finalResults : MOCK_SCHEMES.filter(s => 
      s.title.toLowerCase().includes(query.toLowerCase()) || 
      s.description.toLowerCase().includes(query.toLowerCase())
    );
  } catch (error) {
    console.error("AI Search Error:", error);
    return MOCK_SCHEMES.filter(s => 
      s.title.toLowerCase().includes(query.toLowerCase()) || 
      s.description.toLowerCase().includes(query.toLowerCase())
    );
  }
};

/**
 * Generates personalized recommendations using Gemini 3 Pro for higher reasoning.
 */
export const getAIRecommendations = async (profile: any) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: `CITIZEN PROFILE: ${JSON.stringify(profile)}`,
      config: {
        thinkingConfig: { thinkingBudget: 2000 },
        systemInstruction: `You are the "Gov-Smart 2025-26 Eligibility Engine". 
        Match this citizen's profile to the most beneficial programs for the 2025 fiscal year.

        Consider:
        - Expansion of PM-JAY for all 70+ seniors.
        - Increased Mudra limits to 20L.
        - The new PM Surya Ghar rooftop solar program for homeowners.

        SCHEME ELIGIBILITY DATA: ${JSON.stringify(MOCK_SCHEMES.map(s => ({ 
          id: s.id, 
          title: s.title, 
          category: s.category,
          level: s.level,
          eligibility: s.eligibility 
        })))}

        OUTPUT:
        Return a JSON array of matched scheme IDs.`,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: { type: Type.STRING }
        }
      }
    });

    const text = response.text || '[]';
    const recommendedIds = JSON.parse(text);

    const matches = MOCK_SCHEMES.filter(s => recommendedIds.includes(s.id));
    return matches.length > 0 ? matches : MOCK_SCHEMES.slice(0, 4);
  } catch (error) {
    console.error("AI Recommendation Error:", error);
    return MOCK_SCHEMES.slice(0, 4);
  }
};

