import { GoogleGenAI, Type } from "@google/genai";
import { MOCK_SCHEMES } from "../constants";

/**
 * Searches for relevant schemes using Gemini AI.
 */
export const searchSchemesAI = async (query: string) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `User Query: "${query}". Identify the most relevant schemes from our database.`,
      config: {
        systemInstruction: `You are the "Gov-Smart Navigator". 
        Your task is to identify relevant government schemes from the provided database based on user intent.

        DATABASE: ${JSON.stringify(MOCK_SCHEMES.map(s => ({ 
          id: s.id, 
          title: s.title, 
          description: s.description, 
          category: s.category 
        })))}

        RULES:
        1. Return a JSON array containing the string IDs of relevant database schemes.
        2. Prioritize accuracy based on user needs.
        3. Output MUST be valid JSON.`,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              id: { type: Type.STRING },
              title: { type: Type.STRING }
            }
          }
        }
      }
    });

    const text = response.text || '[]';
    const results = JSON.parse(text);

    const finalResults = results
      .map((res: any) => MOCK_SCHEMES.find(s => s.id === res.id))
      .filter(Boolean);

    return finalResults.length > 0 ? finalResults : MOCK_SCHEMES.filter(s => 
      s.title.toLowerCase().includes(query.toLowerCase()) || 
      s.description.toLowerCase().includes(query.toLowerCase())
    );
  } catch (error) {
    console.error("AI Search Error:", error);
    return MOCK_SCHEMES.filter(s => 
      s.title.toLowerCase().includes(query.toLowerCase()) || 
      s.description.toLowerCase().includes(query.toLowerCase())
    );
  }
};

/**
 * Generates personalized recommendations using Gemini.
 */
export const getAIRecommendations = async (profile: any) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `CITIZEN PROFILE: ${JSON.stringify(profile)}`,
      config: {
        systemInstruction: `You are the "Gov-Smart Eligibility Engine". 
        Match this citizen's profile to the most beneficial programs from our database.

        SCHEME ELIGIBILITY DATA: ${JSON.stringify(MOCK_SCHEMES.map(s => ({ 
          id: s.id, 
          title: s.title, 
          category: s.category,
          level: s.level,
          eligibility: s.eligibility 
        })))}

        OUTPUT:
        Return a JSON array of matched scheme IDs.`,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: { type: Type.STRING }
        }
      }
    });

    const text = response.text || '[]';
    const recommendedIds = JSON.parse(text);

    const matches = MOCK_SCHEMES.filter(s => recommendedIds.includes(s.id));
    return matches.length > 0 ? matches : MOCK_SCHEMES.slice(0, 4);
  } catch (error) {
    console.error("AI Recommendation Error:", error);
    return MOCK_SCHEMES.slice(0, 4);
  }
};

