import { GoogleGenAI, Type } from "@google/genai";
import { MOCK_SCHEMES } from "../constants";

/**
 * Searches for relevant schemes using Gemini AI.
 * Focuses on active 2024-2025 schemes from official database.
 */
export const searchSchemesAI = async (query: string) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `User Query: "${query}". Identify the most relevant active 2024-2025 official schemes.`,
      config: {
        systemInstruction: `You are the "Gov-Smart Navigator". 
        Your task is to identify relevant official government schemes from the provided database.

        DATABASE (MOST RECENT ACTIVE SCHEMES): ${JSON.stringify(MOCK_SCHEMES.map(s => ({ 
          id: s.id, 
          title: s.title, 
          description: s.description, 
          category: s.category,
          updatedAt: s.updatedAt
        })))}

        RULES:
        1. Only return schemes that match the user's intent.
        2. Prioritize recently updated schemes (2024-2025).
        3. Return a JSON array of matched scheme objects with their IDs.
        4. If no exact match found in database, suggest the most related ones.
        5. Output MUST be valid JSON.`,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              id: { type: Type.STRING },
              title: { type: Type.STRING }
            }
          }
        }
      }
    });

    const text = response.text || '[]';
    const results = JSON.parse(text);

    const finalResults = results
      .map((res: any) => MOCK_SCHEMES.find(s => s.id === res.id))
      .filter(Boolean);

    return finalResults.length > 0 ? finalResults : MOCK_SCHEMES.filter(s => 
      s.title.toLowerCase().includes(query.toLowerCase()) || 
      s.description.toLowerCase().includes(query.toLowerCase())
    );
  } catch (error) {
    console.error("AI Search Error:", error);
    return MOCK_SCHEMES.filter(s => 
      s.title.toLowerCase().includes(query.toLowerCase()) || 
      s.description.toLowerCase().includes(query.toLowerCase())
    );
  }
};

/**
 * Generates personalized recommendations using Gemini.
 * Matches profile against the latest 2025 eligibility criteria.
 */
export const getAIRecommendations = async (profile: any) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `CITIZEN PROFILE: ${JSON.stringify(profile)}`,
      config: {
        systemInstruction: `You are the "Gov-Smart Eligibility Engine". 
        Your goal is to match this citizen to official government welfare programs active in 2025.

        SCHEME ELIGIBILITY DATA (2025): ${JSON.stringify(MOCK_SCHEMES.map(s => ({ 
          id: s.id, 
          title: s.title, 
          category: s.category,
          level: s.level,
          eligibility: s.eligibility,
          updatedAt: s.updatedAt
        })))}

        CRITICAL MATCHING RULES:
        - For age >= 70, always prioritize "Ayushman Bharat Senior Citizen Expansion".
        - For rooftop solar intent, match "PM Surya Ghar".
        - For students in higher ed, match "PM-Vidyalaxmi".
        - For rural women in SHGs, match "Lakhpati Didi".
        - Return a JSON array of scheme IDs.`,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: { type: Type.STRING }
        }
      }
    });

    const text = response.text || '[]';
    const recommendedIds = JSON.parse(text);

    const matches = MOCK_SCHEMES.filter(s => recommendedIds.includes(s.id));
    return matches.length > 0 ? matches : MOCK_SCHEMES.slice(0, 4);
  } catch (error) {
    console.error("AI Recommendation Error:", error);
    return MOCK_SCHEMES.slice(0, 4);
  }
};

