                    ${msg.role === 'user' ? 'bg-[#1e293b] text-white rounded-tr-none shadow-navy/20' : 'bg-white text-[#1e293b] border border-gray-100 rounded-tl-none shadow-sm'}
                  `}>
                    <div className="font-medium whitespace-pre-wrap">{msg.text}</div>

