                  value={input}
                  onChange={(e) => setInput(e.target.value)}
                  placeholder={isListening ? "Accumulating speech..." : "Type your question..."}
                  className={`
                    w-full pl-5 pr-11 py-4 bg-gray-50 border border-transparent rounded-2xl 
                    text-sm font-semibold text-[#1e293b] focus:bg-white focus:border-orange-100 outline-none transition-all
                    ${isListening ? 'opacity-60 italic' : ''}
                  `}
                  disabled={isListening}
                />
                <button 
                  type="button" 
                  onClick={toggleListening} 
                  className={`
                    absolute right-2 top-1/2 -translate-y-1/2 w-10 h-10 rounded-xl flex items-center justify-center transition-all
                    ${isListening ? 'bg-red-500 text-white shadow-lg hover:bg-red-600 scale-110' : 'text-gray-400 hover:text-navy'}
                  `}
                >
                  {isListening ? <Square size={16} fill="white" /> : <Mic size={20} />}
                </button>
              </div>

              {!isListening && (
                <button 
                  type="submit" 
                  disabled={!input.trim() || isLoading} 
                  className="
                    w-12 h-12 bg-[#1e293b] text-white rounded-2xl flex items-center justify-center 
                    hover:bg-orange-primary disabled:opacity-20 transition-all shadow-lg active:scale-95
                  "
                >
                  <SendHorizontal size={20} />
                </button>
              )}

              {isListening && (
                <button 
                  type="button"
                  onClick={finishSpeaking}
                  className="
                    px-5 h-12 bg-red-600 text-white rounded-2xl flex items-center justify-center 
                    hover:bg-red-700 transition-all shadow-lg active:scale-95 font-bold text-xs uppercase tracking-wider
                  "
                >
                  Finish
                </button>
              )}
            </form>
          </div>
        </div>
      )}

      {/* Launcher */}
      <div className="relative pointer-events-auto">
        {!isOpen && (
          <div className="absolute inset-0 bg-orange-primary/20 rounded-[2rem] blur-xl animate-pulse"></div>
        )}
        <button 
          onClick={() => { setIsOpen(!isOpen); if(!isOpen) initAudio(); }}
          className={`
            relative w-16 h-16 rounded-[1.8rem] shadow-xl flex items-center justify-center text-white transition-all duration-500 transform hover:scale-110 active:scale-90
            ${isOpen ? 'bg-[#1e293b] rotate-90' : 'bg-gradient-to-br from-orange-400 to-orange-600'}
          `}
        >
          {isOpen ? <X size={28} /> : <Bot size={28} />}
        </button>
      </div>
    </div>
  );
};

