import { 
  signInWithEmailAndPassword, 
  createUserWithEmailAndPassword, 
  updateProfile,
  sendEmailVerification,
  sendPasswordResetEmail,
  signOut,
  AuthError
} from 'firebase/auth';
import { doc, setDoc } from 'firebase/firestore';
import { auth, db } from '../lib/firebase';

const Auth: React.FC = () => {
  const [isLogin, setIsLogin] = useState(true);
  const [isForgotPassword, setIsForgotPassword] = useState(false);
  const [showPassword, setShowPassword] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState<string | null>(null);
  const [verificationEmail, setVerificationEmail] = useState<string | null>(null);
  const [resetEmailSent, setResetEmailSent] = useState<string | null>(null);
  const navigate = useNavigate();
  const location = useLocation();

  // Redirect back to the intended page or default to home
  const from = location.state?.from?.pathname || "/";

  // Form states
  const [formData, setFormData] = useState({
    email: '',
    username: '',
    password: '',
    confirmPassword: ''
  });

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleAuthAction = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError(null);
    setSuccess(null);

    if (isForgotPassword) {
      handleForgotPassword();
      return;
    }

    if (!isLogin && formData.password !== formData.confirmPassword) {
      setError("Passwords do not match");
      setLoading(false);
      return;
    }

    try {
      if (isLogin) {
        // Firebase Login
        try {
          const userCredential = await signInWithEmailAndPassword(auth, formData.email, formData.password);
          const user = userCredential.user;

          if (!user.emailVerified) {
            await sendEmailVerification(user);
            setVerificationEmail(user.email);
            await signOut(auth);
            setLoading(false);
            return;
          }

          const userData = {
            email: user.email,
            username: user.displayName || user.email?.split('@')[0],
            id: user.uid
          };

          localStorage.setItem('gov_smart_user', JSON.stringify(userData));
          window.dispatchEvent(new Event('storage'));

          // SUCCESS: Redirect back to the intended protected page
          navigate(from, { replace: true });
        } catch (err: any) {
          const authError = err as AuthError;
          if (authError.code === 'auth/invalid-credential' || authError.code === 'auth/user-not-found' || authError.code === 'auth/wrong-password') {
            setError("Password or Email Incorrect");
          } else {
            setError("An error occurred during sign in. Please try again.");
          }
          setLoading(false);
        }
      } else {
        // Firebase Register
        try {
          const userCredential = await createUserWithEmailAndPassword(auth, formData.email, formData.password);
          const user = userCredential.user;

          if (formData.username) {
            await updateProfile(user, { displayName: formData.username });
          }

          await setDoc(doc(db, "profiles", user.uid), {
            first_name: formData.username || user.email?.split('@')[0],
            last_name: '',
            email: user.email,
            age: '',
            state: '',
            occupation: '',
            income: '',
            category: 'General',
            created_at: new Date().toISOString()
          });

          await sendEmailVerification(user);
          setVerificationEmail(user.email);
          await signOut(auth);
          setLoading(false);
        } catch (err: any) {
          const authError = err as AuthError;
          if (authError.code === 'auth/email-already-in-use') {
            setError('User already exists. Sign in?');
          } else {
            setError(authError.message || 'An error occurred during registration.');
          }
          setLoading(false);
        }
      }
    } catch (err: any) {
      setError('An unexpected error occurred. Please try again.');
      setLoading(false);
    }
  };

  const handleForgotPassword = async () => {
    if (!formData.email) {
      setError("Please enter your email address first.");
      setLoading(false);
      return;
    }

    try {
      await sendPasswordResetEmail(auth, formData.email);
      setResetEmailSent(formData.email);
      setLoading(false);
    } catch (err: any) {
      const authError = err as AuthError;
      if (authError.code === 'auth/user-not-found') {
        setError("No user found with this email address.");
