          </div>

          {/* Input Area */}
          <div className="p-4 bg-white border-t border-gray-50 flex flex-col gap-3 shrink-0">
            {isListening && (
              <div className="flex items-center justify-center gap-3 px-4 py-2.5 bg-navy text-white rounded-2xl animate-pulse mb-1">
